// --- Shared-framework wrappers ----------------------------------------------
// Self-paced: no cohort start, so every row's date is null by design and the UI
// shows a lesson number rather than a fabricated calendar date (DR-0076).

export function buildManagementStewardshipSchedule(startISO = null) {
  return buildScheduleFor(MANAGEMENT_STEWARDSHIP_MODULES, startISO, MANAGEMENT_STEWARDSHIP_META.cadenceDays);
}

export function managementStewardshipProgressSummary(progress = {}) {
  return progressSummaryFor(MANAGEMENT_STEWARDSHIP_MODULES, progress);
}

export function exportManagementStewardshipCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: MANAGEMENT_STEWARDSHIP_META,
    modules: buildManagementStewardshipSchedule(startISO),
    sessionFlow: MANAGEMENT_STEWARDSHIP_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function managementStewardshipRefs() {
  const seen = new Set();
  for (const m of MANAGEMENT_STEWARDSHIP_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((MANAGEMENT_STEWARDSHIP_META.wordFirst && MANAGEMENT_STEWARDSHIP_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

